head.script:
scwin.onpageload = function() {
    var frameId = $p.getFrameId() || $p.getParameter("w2xPath");
    console.log("onpageload - " + frameId + " Frame");
};
scwin.onpageunload = function() {};
scwin.openPopup = function(fileName, type) {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    var popupId = fileName.substr(0, fileName.indexOf("."));
    var opts = {
        "id": popupId,
        "type": type,
        "width": "560px",
        "height": "530px",
        "top": "100px",
        "left": "100px",
        "popupName": popupId,
        "modal": false,
        "title": popupId
    };
    $p.openPopup(fileName, opts);
};
scwin.btn_openWFrame_onclick = function(e) {
    scwin.openPopup("tabControl_scope_WPFF-221_(WSQ-3504)_wframe1.xml", "wframePopup");
};
scwin.btn_openIFrame_onclick = function(e) {
    scwin.openPopup("tabControl_scope_WPFF-221_(WSQ-3504)_wframe1.xml", "iframePopup");
};
scwin.btn_openTabControlWFrame_onclick = function(e) {
    scwin.openPopup("tabControl_scope_WPFF-221_(WSQ-3504)_tabControl.xml", "wframePopup");
};
scwin.btn_openTabControlIFrame_onclick = function(e) {
    scwin.openPopup("tabControl_scope_WPFF-221_(WSQ-3504)_tabControl.xml", "iframePopup");
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
